function summary(){return `<div class="hero-note summary-hero"><span class="health">● Estado de la operación</span><strong>Decide dónde actuar primero: inventario, demanda, entregas o activos.</strong><span class="subtle">${state.updated}</span></div><section class="summary-priority"><div><span class="eyebrow">Prioridad ejecutiva</span><h2>Cuatro señales para proteger la venta y la continuidad</h2><p>La portada conecta los cuatro casos de uso con una acción concreta.</p></div><button class="summary-refresh" type="button" onclick="connectLive()">Actualizar lectura ↻</button></section><div class="grid kpi-grid"><div class="card metric"><span class="label">Clientes atendidos / mes</span><span class="value">—</span><span class="delta positive">Impacto comercial</span></div><div class="card metric"><span class="label">Tiendas / SKUs cubiertos</span><span class="value">—</span><span class="delta positive">Cobertura de la red</span></div><div class="card metric"><span class="label">Pedidos procesados</span><span class="value">—</span><span class="delta positive">Operación del día</span></div><div class="card metric"><span class="label">Unidades movilizadas</span><span class="value">—</span><span class="delta positive">Flujo físico</span></div></div><section class="summary-actions"><div class="section-heading"><div><h2>Qué requiere atención hoy</h2><span class="subtle">Entra directo al módulo que explica el problema y la siguiente acción.</span></div></div><div class="summary-action-grid"><button class="summary-action risk" data-summary-go="stock"><span class="summary-action-icon">!</span><span><small>CU01 · Riesgo de stock</small><strong><b id="summary-priority-risk">—</b> SKU en riesgo</strong><em><b id="summary-priority-critical">—</b> críticos · Ver reposición</em></span><i>→</i></button><button class="summary-action forecast" data-summary-go="forecast"><span class="summary-action-icon">↗</span><span><small>CU02 · Forecast y reposición</small><strong>Convertir demanda en plan</strong><em>Producto · cantidad · centro · fecha</em></span><i>→</i></button><button class="summary-action operations" data-summary-go="operations"><span class="summary-action-icon">▤</span><span><small>CU03 · Operación</small><strong><b id="summary-priority-orders">—</b> pedidos procesados</strong><em><b id="summary-priority-units">—</b> unidades movilizadas</em></span><i>→</i></button><button class="summary-action maintenance" data-summary-go="maintenance"><span class="summary-action-icon">⚙</span><span><small>CU04 · Mantenimiento</small><strong>Evitar interrupciones</strong><em>Prioriza activos críticos y preventivos</em></span><i>→</i></button></div></section><section class="summary-bottom"><div class="card summary-message"><span class="eyebrow">Lectura de negocio</span><h2>De la señal a la decisión</h2><p>Detectar un riesgo es el inicio: el siguiente paso es movilizar producto, proteger la entrega o intervenir el activo antes de afectar al cliente.</p></div><div class="card summary-legend"><span class="eyebrow">Cómo leer el centro</span><div><b class="legend-pill green">Verde</b><span>flujo bajo control</span></div><div><b class="legend-pill amber">Ámbar</b><span>revisión recomendada</span></div><div><b class="legend-pill red">Rojo</b><span>acción prioritaria</span></div></div></section>`}
document.addEventListener('click',event=>{const button=event.target.closest('[data-summary-go]');if(button){state.page=button.dataset.summaryGo;render();hydrateLiveView();window.scrollTo(0,0)}});
async function connectLive(){
  const cfg=window.LUMINA_CONFIG||{};
  if(!cfg.apiBaseUrl)return;
  const endpoints=['summary','stock-risk','forecast','kpis','inventory-plans','maintenance-risks','maintenance-analytics','operations','operations-analytics'];
  const payloadHasData=payload=>{
    const data=payload?.data;
    if(payload?.count>0)return true;
    if(Array.isArray(data))return data.length>0;
    if(data&&typeof data==='object'){
      const metrics=data.metrics||{};
      if(Object.values(metrics).some(value=>Number(value)>0))return true;
      if(['trend','concentration','streaming_insights','stockout_risks'].some(key=>Array.isArray(data[key])&&data[key].length>0))return true;
      if(Object.values(data).some(value=>Array.isArray(value)&&value.length>0))return true;
      if(Object.values(data).some(value=>typeof value==='number'&&value>0))return true;
    }
    return Boolean(payload?.counts&&Object.values(payload.counts).some(value=>Number(value)>0));
  };
  await Promise.all(endpoints.map(async endpoint=>{
    try{const scenarioQuery=endpoint==='kpis'?'':`&scenario_id=${encodeURIComponent(cfg.scenarioId||'')}`;const limit=endpoint==='stock-risk'||endpoint==='forecast'?100:25;const response=await fetch(`${cfg.apiBaseUrl}/${endpoint}?limit=${limit}${scenarioQuery}`);if(!response.ok)throw new Error(`API ${response.status}`);state.live[endpoint]=await response.json();state.status[endpoint]=payloadHasData(state.live[endpoint])?'online':'amber'}catch(error){state.status[endpoint]=false;console.warn(`Ruta ${endpoint} no disponible`,error)}}));
  await Promise.all(Object.keys(state.master).map(async kind=>{
    try{const response=await fetch(`${cfg.apiBaseUrl}/catalog/${kind}?limit=100`);if(!response.ok)throw new Error(`API ${response.status}`);state.master[kind]=(await response.json()).data||[];state.status[`catalog/${kind}`]=state.master[kind].length?'online':'amber'}catch(error){state.status[`catalog/${kind}`]=false;console.warn(`Catálogo ${kind} no disponible`,error)}}));
  if(state.master.stores.length){const byId=new Map(state.master.stores.map(store=>[store.store_id,store]));riskStores.forEach(row=>{const store=byId.get(row[0]);if(store)row[1]=store.zone_name})}
  const kpiRows=state.live.kpis?.data||[];const currentKpi=kpiRows[0];if(currentKpi){network.orders=Number(currentKpi.orders||0);network.units=Number(currentKpi.units||0)}
  state.liveReady=Boolean(currentKpi);
  window.LUMINA_LIVE=Object.values(state.status).some(Boolean);
  if(state.page!=='assistant'){
    render();
    hydrateLiveView();
  }
  // Cada vista conserva sus propios indicadores y periodos.
}
async function initAuth(){const screen=document.querySelector('#login-screen'),form=document.querySelector('#login-form'),error=document.querySelector('#login-error');const response=await fetch('/auth/me',{credentials:'same-origin'});const current=await response.json();if(current.authenticated){screen.classList.add('hidden');connectLive()}form.addEventListener('submit',async event=>{event.preventDefault();error.textContent='';const data=Object.fromEntries(new FormData(form));const result=await fetch('/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!result.ok){error.textContent=(await result.json()).error||'No fue posible ingresar.';return}screen.classList.add('hidden');connectLive()})}
initAuth();
const topActions=document.querySelector('.top-actions');if(topActions){const userButton=document.querySelector('#user-button');if(userButton){userButton.classList.add('refresh-button');userButton.querySelector('.avatar').textContent='↻';userButton.setAttribute('aria-label','Actualizar datos de GCP');userButton.title='Actualizar datos de GCP';userButton.addEventListener('click',async()=>{userButton.classList.add('is-refreshing');state.updated='Actualizando datos de GCP…';await connectLive();userButton.classList.remove('is-refreshing')})}setInterval(()=>connectLive(),30000)}
function operationsBarChart(rows){const data=(Array.isArray(rows)?rows:[]).filter(r=>r&&r.period_date&&Number(r.orders||0)>0).slice().reverse();if(!data.length)return '<div class="empty">Sin datos de volumen para el periodo seleccionado.</div>';const max=Math.max(...data.map(r=>Number(r.orders||0)),1);const previous=Number(data.at(-2)?.orders||0),current=Number(data.at(-1)?.orders||0),delta=previous?Math.round((current-previous)/previous*100):0;const reading=previous?(delta>=0?`El volumen creció ${Math.abs(delta)}% frente al periodo anterior.`:`El volumen disminuyó ${Math.abs(delta)}% frente al periodo anterior.`):'Se dispone del primer periodo de comparación.';const bars=data.map((r,i)=>`<div class="ops-bar-item ${i===data.length-1?'current':'previous'}"><div class="ops-bar-value">${fmt(Number(r.orders||0))}</div><div class="ops-bar-track"><i style="height:${Math.max(8,Number(r.orders||0)/max*100)}%"></i></div><span>${String(r.period_date).slice(5)}</span></div>`).join('');return `<div class="operations-bars"><div class="chart-legend"><span><i class="legend-dot previous-dot"></i>Periodo anterior</span><span><i class="legend-dot current-dot"></i>Periodo actual</span><strong>${delta>=0?'▲':'▼'} ${Math.abs(delta)}% vs. anterior</strong></div><div class="ops-bars-grid">${bars}</div><div class="chart-callout"><strong>Lectura de negocio:</strong> ${reading} Esta comparación ayuda a anticipar capacidad de preparación y entrega.</div></div>`}
function operationRowMarkup(r){const attention=Number(r.attention||0);const delivered=Number(r.delivered||0);const status=attention>0?'Requiere atención':delivered>0?'Entregado':'Procesado';const type=attention>0?'red':delivered>0?'':'amber';return `<tr><td><strong>Resumen diario · ${r.period_date||'Periodo actual'}</strong></td><td>Red operativa · 32 tiendas</td><td>${fmt(Number(r.units||r.quantity||0))}</td><td>${r.observed_at||r.period_date||'—'}</td><td>${badge(status,type)}</td></tr>`}
function maintenanceSeverityChart(rows){const data=(Array.isArray(rows)?rows:[]).slice().reverse();if(!data.length)return '<div class="empty">Sin tendencia de alertas disponible.</div>';const bars=data.map(r=>{const total=Math.max(1,Number(r.alerts||0)),high=Number(r.high_alerts||0),medium=Number(r.medium_alerts||0),normal=Math.max(0,total-high-medium);return `<div class="maint-bar-item"><strong>${fmt(total)} activos</strong><div class="maint-stack" title="${fmt(total)} activos con alerta"><i class="maint-high" style="height:${high/total*100}%"></i><i class="maint-medium" style="height:${medium/total*100}%"></i><i class="maint-normal" style="height:${normal/total*100}%"></i></div><span>${String(r.period_date).slice(5)}</span></div>`}).join('');return `<div class="maintenance-chart"><div class="chart-legend"><span><i class="legend-dot maint-high-dot"></i>Críticas</span><span><i class="legend-dot maint-medium-dot"></i>Preventivas</span><span><i class="legend-dot maint-normal-dot"></i>Seguimiento</span></div><div class="maint-bars">${bars}</div><div class="chart-callout"><strong>Lectura de negocio:</strong> cada barra representa activos únicos con alerta en el día; los segmentos muestran la proporción de severidad.</div></div>`}
